package com.bocsoft.sqleditor.execution;
import java.util.Locale;import java.util.regex.Matcher;import java.util.regex.Pattern;import org.springframework.stereotype.Component;
@Component public class SqlStatementClassifier {private static final Pattern FIRST=Pattern.compile("(?is)^(?:\\s|/\\*.*?\\*/|--[^\\r\\n]*(?:\\r?\\n|$)|#[^\\r\\n]*(?:\\r?\\n|$))*(\\p{Alpha}+)");
 public StatementType classify(String sql){Matcher m=FIRST.matcher(sql);if(!m.find())return StatementType.OTHER;String w=m.group(1).toUpperCase(Locale.ROOT);if("SELECT".equals(w)||"SHOW".equals(w)||"EXPLAIN".equals(w)||"DESC".equals(w)||"DESCRIBE".equals(w)||"WITH".equals(w))return StatementType.SELECT;if("INSERT".equals(w))return StatementType.INSERT;if("UPDATE".equals(w))return StatementType.UPDATE;if("DELETE".equals(w))return StatementType.DELETE;if("REPLACE".equals(w))return StatementType.REPLACE;if("CREATE".equals(w)||"ALTER".equals(w)||"DROP".equals(w)||"TRUNCATE".equals(w)||"RENAME".equals(w))return StatementType.DDL;return StatementType.OTHER;}}
